<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();$counts=['services'=>(int)$pdo->query('SELECT COUNT(*) FROM services WHERE active=1')->fetchColumn(),'gallery'=>(int)$pdo->query('SELECT COUNT(*) FROM gallery WHERE active=1')->fetchColumn(),'new'=>(int)$pdo->query("SELECT COUNT(*) FROM estimate_requests WHERE status='new'")->fetchColumn(),'total'=>(int)$pdo->query('SELECT COUNT(*) FROM estimate_requests')->fetchColumn(),'drafts'=>(int)$pdo->query('SELECT COUNT(*) FROM content_drafts')->fetchColumn(),'notifications'=>(int)$pdo->query('SELECT COUNT(*) FROM admin_notifications WHERE is_read=0')->fetchColumn()];$recent=$pdo->query('SELECT id,full_name,service_needed,status,created_at FROM estimate_requests ORDER BY id DESC LIMIT 5')->fetchAll();$missing=(int)$pdo->query("SELECT COUNT(*) FROM gallery WHERE active=1 AND (image_path IS NULL OR image_path='')")->fetchColumn();$emailOk=(int)$pdo->query('SELECT COUNT(*) FROM correo WHERE estado=1')->fetchColumn()>0;$areas=(int)$pdo->query('SELECT COUNT(*) FROM service_areas WHERE active=1')->fetchColumn();$attention=[['New estimate requests',$counts['new'],$counts['new']?'Customers are waiting for review.':'No new customer requests.','estimates.php','mail'],['Unpublished content',$counts['drafts'],$counts['drafts']?'A landing page draft is waiting to publish.':'Public content matches the latest saved version.','content.php','edit'],['Gallery images missing',$missing,$missing?'Replace fallback previews with real project images.':'All published gallery items have images.','gallery.php','image'],['Email delivery',$emailOk?'Ready':'Setup',$emailOk?'At least one email configuration is active.':'Configure SMTP or Microsoft Graph.','email.php','mail'],['Service areas',$areas,$areas?'Coverage locations are published.':'Add at least one coverage area.','areas.php','pin']];$pageTitle='Dashboard';$active='dashboard';require __DIR__.'/_header.php';?><div class="page-heading animate-in"><div><p class="eyebrow">DASHBOARD</p>