ge project images and public gallery.'],['areas.php','pin','Service areas','Manage cities, ZIP codes and coverage.'],['seo.php','eye','SEO Manager','Search title, description and social image.'],['health.php','gear','Website Health','Automatic readiness and configuration checks.'],['notifications.php','mail','Activity Center','Notifications and administrator history.'],['backups.php','dashboard','Backup & Restore','Create restore points before major changes.']];foreach($cards as $c):?><a class="manage-card animate-in" href="<?=$c[0]?>"><span class="manage-icon"><?=icon($c[1])?></span><div><strong><?=h($c[2])?></strong><small><?=h($c[3])?></small></div><span class="manage-arrow">→</span></a><?php endforeach;?></div></section><section class="dashboard-section"><div class="section-heading"><div><p class="eyebrow">CUSTOMER REQUESTS</p><h2>Recent free estimates</h2></div><a class="button secondary small" href="estimates.php">View all requests</a></div><?php if(!$recent):?><div class="empty-state"><strong>No requests yet</strong><p>New estimate requests will appear here automatically.</p></div><?php else:?><div class="request-grid"><?php foreach($recent as $r):?><article class="request-card animate-in"><div class="request-top"><div><strong><?=h($r['full_name']?:'Website visitor')?></strong><small><?=h($r['created_at'])?></small></div><span class="badge <?=h($r['status'])?>"><?=h($r['status'])?></span></div><p><?=h($r['service_needed']?:'General project')?></p><a href="estimates.php?view=<?=$r['id']?>">Open request →</a></article><?php endforeach;?></div><?php endif;?></section><?php require __DIR__.'/_footer.php';